piece "Glass Mountain" {
    subtitle "for violin and strings";
    composer "musa";
    copyright "© 2026. Licensed CC BY-SA 4.0.";

    tempo quarter = 72;
    meter 4/4;
    key a minor;

    motif sigh(root: Pitch) {
        root/2
        rest/4
        c5/2
        b4/4
        a4/2
    }

    score {
        part violin {
            clef treble;

            voice lead {
                use sigh(e5);

                transpose down P5 {
                    use sigh(e5);
                }
            }
        }

        part strings {
            voice upper {
                c5/1
                c5/1
                a4/1
                g#4/1
            }

            voice bass {
                // Under the pedal for the whole descent: the harmony is a
                // wash rather than four separate chords, and the pedal is
                // where a page says so.
                mark pedal {
                    a2/1
                    f2/1
                    d2/1
                    e2/1
                }
            }
        }
    }

    // The sound side (roadmap 7.1). Every stage here runs real DSP: the
    // oscillators and envelope are the voice, the filter and its modulation
    // shape it, and the hall is a send to a reverb bus that returns to the
    // master.
    instrument glass_pad conforms note_instrument {
        implementation graph {
            carrier = oscillator(sine);
            shimmer = oscillator(sine, ratio: 2) |> gain(-15 dB);

            mix(carrier, shimmer)
                |> envelope(adsr(attack: 30 ms, decay: 1.8 s, sustain: 0.65, release: 3.5 s))
                |> lowpass(cutoff: 1400 Hz, resonance: 0.7)
                |> output;
        }
    }

    studio {
        lfo = oscillator(sine, frequency: 0.08 Hz)
            |> scale(250 Hz)
            |> bias(1400 Hz);

        modulate lfo -> glass_pad.lowpass.cutoff;

        room hall {
            reverb(room: 0.82, damping: 0.55);
        }

        assign violin -> glass_pad;
        assign strings -> glass_pad;

        route violin -> master;
        route strings -> master;

        send violin -> hall at -18 dB;
        send strings -> hall at -14 dB;
        route hall -> master;
    }
}
